        "query": "union isfuzzy=true AzureDiagnostics, (datatable(TimeGenerated:datetime, ResourceProvider:string, Category:string, StreamType_s:string, RunbookName_s:string, ResultDescription:string)[])\n| where ResourceProvider == 'MICROSOFT.AUTOMATION' and Category == 'JobStreams' and StreamType_s == 'Output' and RunbookName_s == 'Invoke-GhostNicMaintenance'\n| extend raw = tostring(ResultDescription)\n| where raw startswith 'GHNIC_RESULT:'\n| extend event = parse_json(substring(raw, strlen('GHNIC_RESULT:')))\n| extend VmResourceId = tostring(event.VmResourceId), Succeeded = tobool(event.Succeeded), GhostedCount = toint(event.GhostedCount)\n| where Succeeded and isnotnull(GhostedCount)\n| summarize arg_max(TimeGenerated, GhostedCount) by VmResourceId\n| summarize CurrentGhostNics = sum(GhostedCount), VmsWithGhosts = countif(GhostedCount > 0), VmsScanned = count()\n| project Metrics = pack_array(pack('Metric', 'Current ghost NICs', 'Value', CurrentGhostNics), pack('Metric', 'VMs with ghosts', 'Value', VmsWithGhosts), pack('Metric', 'VMs scanned', 'Value', VmsScanned))\n| mv-expand Metrics\n| project Metric = tostring(Metrics.Metric), Value = tolong(Metrics.Value)",
