    {
      "type": 1,
      "content": { "json": "## Current top offenders\n\nLatest successful scan only. VM status is the most recent state observed by the scheduled run, not a live portal readout. Run Detect before removing anything." },
      "name": "current-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let events = union isfuzzy=true AzureDiagnostics, (datatable(TimeGenerated:datetime, ResourceProvider:string, Category:string, StreamType_s:string, RunbookName_s:string, ResultDescription:string)[])\n| where ResourceProvider == 'MICROSOFT.AUTOMATION' and Category == 'JobStreams' and StreamType_s == 'Output' and RunbookName_s == 'Invoke-GhostNicMaintenance'\n| extend raw = tostring(ResultDescription)\n| where raw startswith 'GHNIC_RESULT:'\n| extend event = parse_json(substring(raw, strlen('GHNIC_RESULT:')))\n| extend VmResourceId = tostring(event.VmResourceId), Succeeded = tobool(event.Succeeded), GhostedCount = toint(event.GhostedCount), ValidCount = toint(event.ValidCount), LastScanUtc = todatetime(event.DetectedAtUtc), PowerState = tostring(event.PowerState);\nlet latestStatus = events\n| extend VmStatus = iff(isnotempty(PowerState), PowerState, iff(Succeeded and isnotnull(GhostedCount), 'VM running', ''))\n| where isnotempty(VmStatus)\n| summarize arg_max(TimeGenerated, VmStatus) by VmResourceId\n| project VmResourceId, VmStatus;\nevents\n| where Succeeded and isnotnull(GhostedCount)\n| summarize arg_max(TimeGenerated, GhostedCount, ValidCount, LastScanUtc) by VmResourceId\n| where GhostedCount > 0\n| join kind=leftouter latestStatus on VmResourceId\n| extend VmStatus = coalesce(VmStatus, 'Not recorded')\n| order by GhostedCount desc, LastScanUtc asc\n| project VM = VmResourceId, ['VM status'] = VmStatus, ['Ghost NICs now'] = GhostedCount, ['Valid NICs'] = ValidCount, ['Last scan UTC'] = LastScanUtc",
